insert into public.perguntas_quiz (conteudo_id, enunciado, alternativas, correta, ordem) select id, 'Quem é responsável pela reprojeção de cada obra?', array['O engenheiro da obra, com apoio de orçamentos','Só o diretor','O fornecedor','O financeiro']::text[], 0, 6 from public.conteudos where codigo='TRN-2026-09' and not exists (select 1 from public.perguntas_quiz pq join public.conteudos cc on cc.id=pq.conteudo_id where cc.codigo='TRN-2026-09' and pq.ordem=6);
insert into public.perguntas_quiz (conteudo_id, enunciado, alternativas, correta, ordem) select id, 'A rodada é entregue em qual sistema?', array['ERP','Mereo','BPM','Planilha por e-mail']::text[], 0, 7 from public.conteudos where codigo='TRN-2026-09' and not exists (select 1 from public.perguntas_quiz pq join public.conteudos cc on cc.id=pq.conteudo_id where cc.codigo='TRN-2026-09' and pq.ordem=7);
insert into public.faq (conteudo_id, pergunta, resposta, ordem) select id, 'Contratos com reajuste próprio usam INCC?', 'Não. Use o índice previsto no contrato e registre a exceção na aba de premissas.', 0 from public.conteudos where codigo='TRN-2026-09' and not exists (select 1 from public.faq ff join public.conteudos cc on cc.id=ff.conteudo_id where cc.codigo='TRN-2026-09' and ff.ordem=0);
