-- Como lançar uma medição de contrato
select s.id, 'Como lançar uma medição de contrato', 'video', 'pilula', 6, null, 'POP-ENG-014', 'Passo a passo para registrar o boletim de medição (BM) de um empreiteiro no ERP, conferir quantidades contra o contrato e enviar para aprovação do gestor da obra.', array['medição','boletim de medição','contratos','ERP']::text[], true, coalesce((select array_agg(id) from public.setores where nome = any(array['Engenharia de Obras','Planejamento']::text[])), '{}'), true, 70, 3, 0, 30, true, 'Excelência Operacional', '2026-08-12'::timestamptz
from public.secoes s where s.slug='eng-erp' and not exists (select 1 from public.conteudos where codigo='POP-ENG-014');

